import React, { useEffect, useState } from "react";
import { Modal, Button, Typography, Divider, Space, Table } from "antd";
// import moment from "moment";
import moment from "moment";
import { currencyFormatTH } from "../../utils/Utils";

const { Text } = Typography;
export default function TermFeeHistoryModal({ open, data, onClose, onDelete }) {
  useEffect(() => {
    console.log(data);
  }, [open]);

  const handleClickCancel = (rec) => {
    Modal.confirm({
      title: `ยกเลิกรายการ`,
      content: `ต้องการยกเลิกรายการชำระ เทอม: ${rec.semester} จำนวนชำระ: ${rec.amount}`,
      centered: true,
      onOk: () => {
        onDelete(rec);
      },
    });
  };

  const handleClose = () => {
    onClose(false);
  };

  const columns = [
    {
      title: `วันที่ชำระ`,
      // dataIndex: "payment_date",
      key: "payment_date",
      render: (recode) => {
        return (
          <Text>
            {moment(recode.payment_date || recode.created_date).format("ll")}
          </Text>
        );
      },
    },
    {
      title: `ปีการศึกษา`,
      dataIndex: "year",
      key: "year",
      render: (recode) => {
        return <Text>{Number(recode) + 543}</Text>;
      },
    },
    {
      title: "เทอม",
      dataIndex: "semester",
      key: "semester",
    },
    {
      title: `จำนวนเงิน`,
      // dataIndex: "user_type",
      key: "amount",
      render: (recode) => {
        return <Text>{currencyFormatTH(recode.amount)}</Text>;
      },
    },
    {
      title: "",
      // dataIndex: "edit",
      key: "edit",
      render: (recode) => {
        return (
          <Space>
            <Button type="link" onClick={() => handleClickCancel(recode)}>
              ยกเลิก
            </Button>
          </Space>
        );
      },
    },
  ];

  return (
    <Modal
      title="รายการชำระ"
      centered={true}
      open={open}
      width={800}
      // onOk={handleSubmit}
      closeIcon={false}
      destroyOnClose={true}
      footer={[
        //   <Button key="submit" type="primary" onClick={form.submit}>
        //     บันทึก
        //   </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Divider />
        <Table columns={columns} dataSource={data} rowKey={"id"} />
      </div>
    </Modal>
  );
}
