import React from "react";
import { Routes, Route } from "react-router-dom";
import TermPaymentRoute from "../pages/payment/Routers";
import StudentListRoute from "../pages/term_fees/Routers";
import UserListRoute from "../pages/user/Routers";
import { useSelector } from "react-redux";

export default function Routers() {
  const user = useSelector((state) => state.userData);

  if (user.role_id === 1) {
    return (
      <Routes>
        {/* <Route path="term-payment/*" element={<TermPaymentRoute />} /> */}
        <Route path="term-payment-list/*" element={<StudentListRoute />} />
        <Route path="users/*" element={<UserListRoute />} />
      </Routes>
    );
  } else {
    return (
      <Routes>
        <Route path="term-payment/*" element={<TermPaymentRoute />} />
      </Routes>
    );
  }

  // } else
  //   return (
  //     <Routes>
  //       {/* <Route path="products/*" element={<ProductsRoute />} /> */}
  //       {/* <Route path="retails/*" element={<RetailRoute />} /> */}
  //       {/* <Route path="users/*" element={<UsersRoute />} /> */}
  //     </Routes>
  //   );
}
