import React, { useEffect, useState } from "react";
import {
  Modal,
  Button,
  Typography,
  Divider,
  Radio,
  Space,
  InputNumber,
  DatePicker,
  TimePicker,
  Image,
  Input,
  Form,
} from "antd";
// import moment from "moment";
import { useDispatch, useSelector } from "react-redux";
import moment from "moment";

const { Text } = Typography;

export default function AddYearModal({ open, onSubmit, onClose }) {
  const [year, setYear] = useState(moment().format("YYYY"));

  const handleClose = () => {
    onClose(false);
  };

  const handleSubmit = (values) => {
    onSubmit(year);
  };

  const onChangeDate = (_, dateString) => {
    setYear(dateString);
  };

  return (
    <Modal
      title="เพิ่มตารางค่าเทอมปีการศึกษาใหม่"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      destroyOnClose={true}
      footer={[
        <Button key="submit" type="primary" onClick={handleSubmit}>
          เพิ่ม
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Divider />
        <div style={{ justifyContent: "space-between", display: "flex" }}>
          <Text strong>เลือกปีการศึกษา</Text>
          <Space>
            <DatePicker picker="year" onChange={onChangeDate} />
            <Text strong>{moment(year).add(543, "years").format("YYYY")}</Text>
          </Space>
        </div>

        <Divider />
      </div>
    </Modal>
  );
}
