import React, { useEffect, useState } from "react";
import {
  Modal,
  Button,
  Typography,
  Divider,
  Radio,
  Space,
  InputNumber,
  DatePicker,
  TimePicker,
  Image,
  Input,
  Form,
} from "antd";
// import moment from "moment";
import { useDispatch, useSelector } from "react-redux";
import moment from "moment";

const { Text } = Typography;

export default function EditTermPaymentModal({
  open,
  data,
  onSubmit,
  onClose,
}) {
  const user = useSelector((state) => state.token);
  const [form] = Form.useForm();

  const [mark, setMark] = useState(null);
  const [date, setDate] = useState("");
  const [time, setTime] = useState("");

  useEffect(() => {
    // console.log("USER", user);

    setMark(null);
    setDate("");
    setTime("");
  }, [data]);

  const handleClose = () => {
    onClose(false);
    form.resetFields();
  };

  const handleSubmit = (values) => {
    const result = {
      ...data,
      ...values,
      mark: mark,
      payment_date: null,
    };

    if (date !== "" && time !== "") {
      onSubmit({ ...result, payment_date: date + " " + time });
    } else {
      onSubmit({ ...result });
    }
    form.resetFields();
  };

  const onChangeDate = (date, dateString) => {
    setDate(dateString);
  };

  const onChangeTime = (time, timeString) => {
    setTime(timeString);
  };
  const onFinishFailed = (errorInfo) => {
    console.log("Failed:", errorInfo);
  };

  return (
    <Modal
      title="ชำระค่าเทอม"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      destroyOnClose={true}
      footer={[
        <Button key="submit" type="primary" onClick={form.submit}>
          บันทึก
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Divider />
        <Form
          form={form}
          labelCol={{
            span: 8,
          }}
          wrapperCol={{
            span: 18,
          }}
          layout="horizontal"
          onFinish={handleSubmit}
          onFinishFailed={onFinishFailed}
        >
          <Form.Item
            name="semester"
            label="ชำระค่าเทอม"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
            // initialValue={eventSelect}
          >
            <Radio.Group>
              <Space>
                <Radio value={1}>เทอม 1</Radio>
                <Radio value={2}>เทอม 2</Radio>
              </Space>
            </Radio.Group>
          </Form.Item>
          <Form.Item
            name="amount"
            label="จำนวนเงิน"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <InputNumber
              size="large"
              name="amount"
              style={{ width: "100%" }}
              formatter={(value) =>
                `${value}`.replace(/\B(?=(\d{3})+(?!\d))/g, ",")
              }
            />
          </Form.Item>
        </Form>

        <Divider />
        <div
          style={{
            display: "flex",
            alignItems: "center",
            flexDirection: "column",
          }}
        >
          <Text type="secondary">วันเวลาที่ชำระ : (กรอกให้ตรงกับสลิป)</Text>
          <Space>
            <DatePicker onChange={onChangeDate} />
            <TimePicker onChange={onChangeTime} />
          </Space>
        </div>

        <Divider />
      </div>
    </Modal>
  );
}
