import React, { useEffect, useState } from "react";
import { Modal, Button, Typography, Divider, Input, Form, Select } from "antd";
// import moment from "moment";
import { useDispatch, useSelector } from "react-redux";
import moment from "moment";

const { Text } = Typography;

const titleNameItems = [
  { value: "เด็กชาย", label: "เด็กชาย" },
  { value: "เด็กหญิง", label: "เด็กหญิง" },
  { value: "นาย", label: "นาย" },
  { value: "นางสาว", label: "นางสาว" },
];

const gradeLevelItems = [
  { value: "เตรียมอนุบาล", label: "เตรียมอนุบาล" },
  { value: "อนุบาล", label: "อนุบาล" },
  { value: "ป.1", label: "ป.1" },
  { value: "ป.2", label: "ป.2" },
  { value: "ป.3", label: "ป.3" },
  { value: "ป.4", label: "ป.4" },
  { value: "ป.5", label: "ป.5" },
  { value: "ป.6", label: "ป.6" },
  { value: "ม.1", label: "ม.1" },
  { value: "ม.2", label: "ม.2" },
  { value: "ม.3", label: "ม.3" },
  { value: "ม.4", label: "ม.4" },
  { value: "ม.5", label: "ม.5" },
  { value: "ม.6", label: "ม.6" },
];

const userTypeItems = [
  { value: "ทั่วไป", label: "ทั่วไป" },
  { value: "นักเรียนทุน", label: "นักเรียนทุน" },
  { value: "ลูกครู", label: "ลูกครู" },
  { value: "ลูกคนที่ 2", label: "ลูกคนที่ 2" },
];

const payTypeItems = [
  { value: "จ่ายครั้งเดียว", label: "จ่ายครั้งเดียว" },
  { value: "แบ่งจ่าย", label: "แบ่งจ่าย" },
];

const statusItems = [
  { value: "กำลังศึกษา", label: "กำลังศึกษา" },
  { value: "จบการศึกษา", label: "จบการศึกษา" },
  { value: "ออก", label: "ออก" },
];
export default function EditStudentModal({
  open,
  data,
  onSubmit,
  onClose,
  onDelete,
}) {
  // const user = useSelector((state) => state.token);
  const [form] = Form.useForm();

  useEffect(() => {
    // console.log("Edit", data);
    form.setFieldsValue({ ...data });
  }, [data]);

  const handleClose = () => {
    form.resetFields();
    onClose(false);
  };

  const handleClickDelete = () => {
    onDelete(data);
  };

  const handleSubmit = (values) => {
    // const title_name = titleNameItems.filter(
    //   (item) => item.value === values.title_name
    // );
    // const grade_level = gradeLevelItems.filter(
    //   (item) => item.value === values.grade_level
    // );
    // const user_type = userTypeItems.filter(
    //   (item) => item.value === values.user_type
    // );

    const user_name = values.student_id?.replace(/[^a-zA-Z0-9]/g, "");
    const idcard = values.idcard?.replace(/[^a-zA-Z0-9]/g, "");

    onSubmit({
      id: data.id,
      ...values,
      user_name,
      idcard,
      // title_name: title_name[0].label,
      // grade_level: grade_level[0].label,
      // user_type: user_type[0].label,
    });
    // form.resetFields();
  };

  const onFinishFailed = (errorInfo) => {
    console.log("Failed:", errorInfo);
  };

  return (
    <Modal
      title="แก้ไขรายชื่อนักเรียน"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      destroyOnClose={true}
      footer={[
        <Button
          key="delete"
          color="danger"
          variant="outlined"
          onClick={handleClickDelete}
        >
          ลบรายชื่อนี้
        </Button>,
        <Button key="submit" type="primary" onClick={form.submit}>
          บันทึก
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Divider />
        <Form
          form={form}
          labelCol={{
            span: 8,
          }}
          wrapperCol={{
            span: 18,
          }}
          layout="horizontal"
          onFinish={handleSubmit}
          onFinishFailed={onFinishFailed}
        >
          <Form.Item
            name="student_id"
            label="เลขประจำตัว"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Input style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item
            name="idcard"
            label="เลขบัตรประชาชน"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Input style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item
            name="title_name"
            label="คำนำหน้าชื่อ"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Select
              placeholder="เลือกคำนำหน้า"
              allowClear
              options={titleNameItems}
            />
          </Form.Item>
          <Form.Item
            name="fullname"
            label="ชื่อ-สกุล"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Input style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item
            name="grade_level"
            label="ระดับชั้นปี"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Select
              placeholder="เลือกระดับชั้น"
              allowClear
              options={gradeLevelItems}
            />
          </Form.Item>
          <Form.Item
            name="user_type"
            label="ประเภทนักเรียน"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Select
              placeholder=" เลือกประเภทนักเรียน"
              allowClear
              options={userTypeItems}
            />
          </Form.Item>
          <Form.Item name="mark" label="หมายเหตุ">
            <Input style={{ width: "100%" }} />
          </Form.Item>
          <Form.Item
            name="payment_type"
            label="การชำระค่าเทอม"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Select
              placeholder="เลือกประเภทการชำระค่าเทอม"
              allowClear
              options={payTypeItems}
            />
          </Form.Item>
          <Form.Item
            name="status"
            label="สถานะ"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
          >
            <Select placeholder="เลือกสถานะ" allowClear options={statusItems} />
          </Form.Item>
        </Form>

        <Divider />
      </div>
    </Modal>
  );
}
