import React, { useEffect, useState } from "react";
import { Modal, Button, Divider, Radio, Space, Form } from "antd";
// import moment from "moment";
// import { useDispatch, useSelector } from "react-redux";

export default function GradeLevelModal({ open, onSubmit, onClose }) {
  // const user = useSelector((state) => state.userData);
  const [form] = Form.useForm();

  const handleClose = () => {
    onClose(false);
    form.resetFields();
  };

  const handleSubmit = (values) => {
    // const grade_level = gradeLevelItems.filter(grade => grade.value === values
    onSubmit(values.status);
    form.resetFields();
  };
  const onFinishFailed = (errorInfo) => {
    console.log("Failed:", errorInfo);
  };

  return (
    <Modal
      title="เลื่อนระดับชั้นนักเรียนทุกคน"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      destroyOnClose={true}
      footer={[
        <Button key="submit" type="primary" onClick={form.submit}>
          บันทึก
        </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Divider />
        <Form
          form={form}
          labelCol={{
            span: 8,
          }}
          wrapperCol={{
            span: 18,
          }}
          layout="horizontal"
          onFinish={handleSubmit}
          onFinishFailed={onFinishFailed}
        >
          <Form.Item
            name="status"
            label="เลื่อนระดับชั้น"
            rules={[{ required: true, message: "ต้องไม่เว้นว่าง!" }]}
            // initialValue={eventSelect}
          >
            <Radio.Group>
              <Space direction="vertical">
                <Radio value={1}>เลื่อนขึ้น 1 ชั้น</Radio>
                <Radio value={2}>เลื่อนลง 1 ชั้น</Radio>
              </Space>
            </Radio.Group>
          </Form.Item>
        </Form>

        <Divider />
      </div>
    </Modal>
  );
}
