import React, { useState, useEffect } from "react";
import { Button, Typography, Modal, Divider } from "antd";
import { currencyFormatTH, extractNumbers } from "../../utils/Utils";
import QRCode from "qrcode";

const { Text } = Typography;

const QRCODE_URL =
  "https://asia-east2-fir-express-c1aec.cloudfunctions.net/aa/loans";
export default function TermPaymentQRCode({ open, data, onSubmit, onClose }) {
  const [urlLink, setUrlLink] = useState(null);
  const [detail, setDetail] = useState(null);
  const [qrCode, setQRCode] = useState("");

  useEffect(() => {
    // console.log("DATA", data);
    if (data) {
      const year = data.year + 543;
      const studentNumber = extractNumbers(data.student_id);
      const obj = {
        prefix: "|",
        taxId: "0994002773762",
        suffix: "01",
        ref1: year - 2500 + "" + data.term_number + "0",
        ref2: studentNumber,
        amount: data?.term_fees * 100,
      };
      setDetail(obj);
      generateQRCode(obj);
      // const url =
      //   QRCODE_URL +
      //   "/qr/" +
      //   obj.taxId + // เลขประจำตัวผู้เสียภาษี
      //   "/" +
      //   obj.suffix + // Suffix
      //   "/" +
      //   obj.ref1 + // REF1
      //   "/" +
      //   obj.ref2 + // REF2
      //   "/" +
      //   obj.amount; // จำนวนเงินชำระ

      // console.log("OBJ", obj.ref2);

      // setUrlLink(url);
    }
  }, [data]);

  const generateQRCode = async (formData) => {
    const { prefix, taxId, suffix, ref1, ref2, amount } = formData;

    // ฟอร์แมตข้อมูลตามที่กำหนด
    const formattedData = `${prefix}${taxId}${suffix}\r\n${ref1}\r\n${ref2}\r\n${amount}`;

    try {
      const qrCodeUrl = await QRCode.toDataURL(formattedData);
      setQRCode(qrCodeUrl);
    } catch (err) {
      console.error(err);
    }
  };

  const handleSubmit = () => {};

  const handleClose = () => {
    // setUrlLink(null);
    setQRCode(null);
    setDetail(null);
    onClose(false);
  };

  return (
    <Modal
      title="ชำระค่าเทอม"
      centered={true}
      open={open}
      onOk={handleSubmit}
      closeIcon={false}
      destroyOnClose={true}
      footer={[
        // <Button key="submit" type="primary" onClick={handleSubmit}>
        //   บันทึก
        // </Button>,
        <Button key="close" onClick={handleClose}>
          ปิด
        </Button>,
      ]}
    >
      <div>
        <Divider />
        <div style={{ flexDirection: "column", display: "flex" }}>
          <div style={{ justifyContent: "space-between", display: "flex" }}>
            <Text type="secondary">ชื่อบัญชี</Text>
            <Text strong>บริษัท กอบัวงาม จำกัด</Text>
          </div>
          <div style={{ justifyContent: "space-between", display: "flex" }}>
            <Text type="secondary">เลขผู้เสียภาษีอากร</Text>
            <Text strong>{detail?.taxId}</Text>
          </div>
          <div style={{ justifyContent: "space-between", display: "flex" }}>
            <Text type="secondary">REF1</Text>
            <Text strong>{detail?.ref1}</Text>
          </div>
          <div style={{ justifyContent: "space-between", display: "flex" }}>
            <Text type="secondary">REF2</Text>
            <Text strong>{detail?.ref2}</Text>
          </div>
          <div style={{ justifyContent: "space-between", display: "flex" }}>
            <Text type="secondary">จำนวนเงินชำระ</Text>
            <Text strong>{currencyFormatTH(data?.term_fees)}</Text>
          </div>
        </div>
        {/* <div
          style={{ justifyContent: "center", display: "flex", marginTop: 8 }}
        >
          <Button onClick={handleClickPDF}>ดาวโหลดใบจ่ายเงินแบบ PDF</Button>
        </div> */}

        <Divider />
        {qrCode ? (
          <>
            <div
              style={{
                flexDirection: "column",
                display: "flex",
                alignItems: "center",
              }}
            >
              <Text strong>
                แตะค้างที่ QR CODE เพื่อบันทึกรูปลงอัลบั้มรูป หรือแคปหน้าจอ
              </Text>
              <Text strong>สามารถชำระผ่านแอพธนาคาร</Text>
            </div>

            <img
              alt=""
              style={{ justifySelf: "center", display: "flex" }}
              width={300}
              src={qrCode}
              crossOrigin="anonymous"
            />
          </>
        ) : null}

        <Divider />
      </div>
    </Modal>
  );
}
