import React, { useEffect, useState } from "react";
import baseAPI from "../../api/baseAPI";
import {
  message,
  Button,
  DatePicker,
  Divider,
  Modal,
  Space,
  Table,
  Tag,
  Tooltip,
  Typography,
  Select,
} from "antd";
import { EditOutlined } from "@ant-design/icons";
import { currencyFormat, currencyFormatTH } from "../../utils/Utils";
import EditTermFeeModal from "./EditTermFeeModal";
import AddYearModal from "./AddYearModal";
import moment from "moment";

const { Text } = Typography;
export default function TermFeeList({ year }) {
  const [gradeList, setGradeList] = useState([]);
  const [termFeeList, setTermFeeList] = useState([]);
  const [termFeeListHolder, setTermFeeListHolder] = useState([]);
  const [dataSelected, setDataSelected] = useState(null);
  const [openEditTermModal, setOpenEditTermModal] = useState(false);
  const [openAddYearModal, setOpenAddYearModal] = useState(false);

  const [messageApi, contextHolder] = message.useMessage();

  useEffect(() => {
    getTermFeeList(year);
  }, [year]);

  const getTermFeeList = async (year) => {
    const result = await baseAPI.get(`term-fees`, { params: { year } });
    const data = result.data;
    setTermFeeList(data);
    setTermFeeListHolder(data);

    // const sortedValues = data.toSorted((a, b) => b.donate - a.donate);
    const uniqueGrade = new Set();
    const uniqueData = data.filter((item) => {
      if (uniqueGrade.has(item.grade_level)) {
        return false;
      } else {
        uniqueGrade.add(item.grade_level);
        return true;
      }
    });
    setGradeList(uniqueData);
  };

  const handleClickEdit = (data) => {
    setOpenEditTermModal(true);
    // console.log("EDIT", data);
    setDataSelected(data);
  };

  const handleChangeGradeLevels = (value) => {
    const result = termFeeListHolder.filter(
      (item) => item.grade_level === value
    );
    setTermFeeList(result);
  };

  const updateTermFee = async (data) => {
    await baseAPI
      .put(`/term-fees`, data)
      .then((res) => {
        messageApi.open({
          type: "success",
          content: "แก้ไขค่าเทอมสำเร็จ",
        });
        // Modal.success({
        //   title: `สำเร็จ`,
        //   content: "แก้ไขค่าเทอมสำเร็จ",
        //   centered: true,
        // });
        // getTermFeeList();
        const termUpdateList = termFeeList.map((term) => {
          if (term.id === data.id) {
            return { ...data };
          } else return { ...term };
        });
        setTermFeeList(termUpdateList);
      })
      .catch((err) => {
        Modal.error({
          title: `ผิดพลาด`,
          content: "Error: " + err.message,
          centered: true,
        });
      });
  };

  const handleSubmitTerm = (data) => {
    // console.log("SUBMIT", data);
    Modal.confirm({
      title: `ยืนยันข้อมูล`,
      content: `ตรวจสอบข้อมูลถูกต้องแล้ว ต้องการบันทึกข้อมูล?`,
      centered: true,
      onOk: () => {
        updateTermFee(data);
        setOpenEditTermModal(false);
      },
    });
  };

  const handleAddYear = () => {
    setOpenAddYearModal(true);
  };

  const addYear = async (year) => {
    await baseAPI
      .post(`/term-fees/${year}`)
      .then((res) => {
        console.log(res.data);
        messageApi.open({
          type: "success",
          content: "เพิ่มปีการศึกษาสำเร็จ",
        });

        // getTermFeeList();
        // const termUpdateList = termFeeList.map((term) => {
        //   if (term.id === data.id) {
        //     return { ...data };
        //   } else return { ...term };
        // });
        // setTermFeeList(termUpdateList);
      })
      .catch((err) => {
        Modal.error({
          title: `ผิดพลาด`,
          content: "Error: " + err.message,
          centered: true,
        });
      });
  };

  const handleSubmitYear = (year) => {
    // console.log("handleSubmitYear", year);
    Modal.confirm({
      title: "ยื่นยันข้อมูล",
      content: `ต้องการเพิ่มปีการศึกษา ${moment(year)
        .add(543, "years")
        .format("YYYY")} ?`,
      centered: true,
      onOk: () => {
        addYear(year);
        setOpenAddYearModal(false);
      },
    });
  };

  const columns = [
    // {
    //   title: "ปีการศึกษา",
    //   // dataIndex: "user_type",
    //   key: "year",
    //   render: (recode) => {
    //     return (
    //       <>
    //         <Text>ปีการศึกษา {recode.year + 543}</Text>
    //       </>
    //     );
    //   },
    // },
    {
      title: "ระดับชั้น",
      dataIndex: "grade_level",
      key: "grade_level",
    },
    {
      title: "ประเภทนักเรียน",
      dataIndex: "user_type",
      key: "user_type",
    },
    {
      title: "ค่าเทอม",
      // dataIndex: "term_fees",
      key: "term_fees",
      render: (recode) => {
        return (
          <>
            <Text> {currencyFormat(recode.term_fees)}</Text>
          </>
        );
      },
    },

    {
      title: "",
      // dataIndex: "edit",
      key: "edit",
      render: (recode) => {
        return (
          <Tooltip title="แก้ไขค่าเทอม">
            <Button
              type="primary"
              shape="circle"
              icon={<EditOutlined />}
              onClick={() => handleClickEdit(recode)}
            />
          </Tooltip>
        );
      },
    },
  ];

  return (
    <div>
      {contextHolder}
      <div
        style={{
          justifyContent: "space-between",
          display: "flex",
          marginBottom: 24,
        }}
      >
        <>
          <Space>
            <Text strong>เลือกระดับชั้น</Text>
            <Select
              showSearch
              style={{ width: 200 }}
              placeholder="เลือกชั้นปี"
              onChange={handleChangeGradeLevels}
              filterOption={(input, option) =>
                (option?.label ?? "")
                  .toLowerCase()
                  .includes(input.toLowerCase())
              }
              options={gradeList.map((grade) => ({
                label: grade.grade_level,
                value: grade.grade_level,
              }))}
            />
          </Space>
        </>
        {/* <>
          <Space>
          
            <Button type="primary" onClick={handleAddYear}>
              เพิ่มปีการศึกษา
            </Button>
          </Space>
        </> */}
      </div>
      <Table columns={columns} dataSource={termFeeList} bordered />
      <EditTermFeeModal
        data={dataSelected}
        onSubmit={handleSubmitTerm}
        open={openEditTermModal}
        onClose={setOpenEditTermModal}
      />
      {/* <AddYearModal
        //  data={dataSelected}
        onSubmit={handleSubmitYear}
        open={openAddYearModal}
        onClose={setOpenAddYearModal}
      /> */}
    </div>
  );
}
